  protected void init(Graph<T> G, Iterator<? extends T> nodes) {
    this.G = G;
    roots = nodes;
    if (roots.hasNext()) {
      theNextElement = roots.next();
    } else {
      theNextElement = null;
    }
  }

  private boolean empty() {
    return size() == 0;
  }

